css:
.skxp-root{position:absolute;inset:0;overflow:hidden;background:var(--wa-bg, #05070d);z-index:5}
.skxp-Modal-Title{width:100%;display:flex;align-items:center;justify-content:space-between}
.skxp-Modal-Title>.t{font-weight:600;font-size:20px;color:var(--wa-text, #fff);white-space:nowrap}
.skxp-Close-Button{width:24px;height:24px;box-sizing:border-box;display:flex;align-items:center;justify-content:center;border:.75px solid var(--wa-line, #e7e9eb);border-radius:4px;cursor:pointer;background-image:linear-gradient(137.8156deg,color-mix(in srgb, var(--wa-point, rgb(209 223 255)) 20%, transparent) 52.344%,color-mix(in srgb, var(--wa-point, rgb(209 223 255)) 0%, transparent) 52.344%),linear-gradient(90deg,var(--wa-surface, #404554) 0%,var(--wa-surface, #404554) 100%)}
.skxp-Icon-Action-Close{width:12px;height:12px;display:block}
.skxp-Close-Button{transition:background-color .12s ease,border-color .12s ease,transform .08s ease}
.skxp-Close-Button:hover{border-color:var(--wa-line, #fff);background-color:color-mix(in srgb, var(--wa-danger, rgb(228 87 90)) 85%, transparent)}
.skxp-Close-Button:hover .skxp-Icon-Action-Close{filter:brightness(2.2)}
.skxp-Close-Button:active{transform:scale(.92)}
.skxp-root{--skxp-sev-all:#cccccc;--skxp-sev-critical:#e4575a;--skxp-sev-major:#fc9126;--skxp-sev-minor:#e3af31;--skxp-sev-warning:#4cb5ff}
